#include <cmath>

// Hidden: the test kit (TEST, CHECK, CHECK_CLOSE), bs_call, bs_put,
// bs_delta_call, tree_call(s, k, r, sigma, t, n) and norm_cdf.
const double S = 100, K = 100, R = 0.05, SIG = 0.2, T = 1;

TEST(test_call_tiny_vol) {
    CHECK_CLOSE(bs_call(S, K, R, 1e-6, T), S - K * std::exp(-R * T), 1e-6);
}

TEST(test_call_deep_out) {
    CHECK(bs_call(50, K, R, SIG, T) < 0.01);
}

TEST(test_parity) {
    CHECK_CLOSE(bs_call(S, K, R, SIG, T) - bs_put(S, K, R, SIG, T), S - K * std::exp(-R * T), 1e-9);
}

TEST(test_known_values) {
    CHECK_CLOSE(bs_call(S, K, R, SIG, T), 10.4506, 1e-4);
    CHECK_CLOSE(bs_put(S, K, R, SIG, T), 5.5735, 1e-4);
}

TEST(test_tree_converges) {
    CHECK_CLOSE(tree_call(S, K, R, SIG, T, 512), bs_call(S, K, R, SIG, T), 0.01);
}

TEST(test_delta_by_bumping) {
    double h = 0.01;
    double fd = (bs_call(S + h, K, R, SIG, T) - bs_call(S - h, K, R, SIG, T)) / (2 * h);
    CHECK_CLOSE(bs_delta_call(S, K, R, SIG, T), fd, 1e-5);
}

