#include <cmath>
#include <cstdio>
#include <string>
#include <vector>

struct ZqTest { const char* name; void (*fn)(); };
std::vector<ZqTest>& zq_registry() { static std::vector<ZqTest> t; return t; }
struct ZqAdd { ZqAdd(const char* n, void (*f)()) { zq_registry().push_back({n, f}); } };
int zq_bad = 0, zq_passed = 0, zq_failed = 0;

#define TEST(name) void name(); static ZqAdd name##_zq(#name, name); void name()
#define CHECK(cond) do { if (!(cond)) { ++zq_bad; std::printf("  %s:%d: CHECK(%s) failed\n", __FILE__, __LINE__, #cond); } } while (0)
#define CHECK_CLOSE(a, b, tol) do { double zq_a = (a), zq_b = (b); if (!(std::fabs(zq_a - zq_b) <= (tol))) { ++zq_bad; std::printf("  %s:%d: CHECK_CLOSE(%s, %s, %s) failed: %.10g and %.10g\n", __FILE__, __LINE__, #a, #b, #tol, zq_a, zq_b); } } while (0)
#include <algorithm>
#include <stdexcept>

class Payoff {
public:
    virtual ~Payoff() = default;
    virtual double operator()(double spot) const = 0;
};
class Call : public Payoff {
public:
    explicit Call(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(spot - strike_, 0.0); }
private:
    double strike_;
};
class Put : public Payoff {
public:
    explicit Put(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(strike_ - spot, 0.0); }
private:
    double strike_;
};

long long zq_trees = 0;

// Level 2's pricer: one row of n + 1 values, reused at every step.
double crr_u(double sigma, double dt) { return std::exp(sigma * std::sqrt(dt)); }

std::vector<double> terminal_values(const Payoff& payoff, double s, double u, double d, int n) {
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j)
        v[j] = payoff(s * std::pow(u, j) * std::pow(d, n - j));
    return v;
}

void step_back(std::vector<double>& v, int i, double q, double disc) {
    for (int j = 0; j <= i; ++j)
        v[j] = disc * (q * v[j + 1] + (1 - q) * v[j]);
}

double tree_price(const Payoff& payoff, double s, double u, double d,
                  double growth, int n, bool american) {
    double q = (growth - d) / (u - d);
    if (!(q > 0.0 && q < 1.0))
        throw std::invalid_argument("q must lie strictly between 0 and 1");
    std::vector<double> v = terminal_values(payoff, s, u, d, n);
    for (int i = n - 1; i >= 0; --i) {
        step_back(v, i, q, 1.0 / growth);
        if (american)
            for (int j = 0; j <= i; ++j)
                v[j] = std::max(v[j], payoff(s * std::pow(u, j) * std::pow(d, i - j)));
    }
    return v[0];
}

double binomial_price(const Payoff& payoff, double s, double r,
                      double sigma, double t, int n, bool american) {
    ++zq_trees;
    if (t == 0.0) return payoff(s);
    double dt = t / n;
    double u = crr_u(sigma, dt);
    return tree_price(payoff, s, u, 1.0 / u, std::exp(r * dt), n, american);
}

double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }

double bs_call_ok(double s, double k, double r, double sigma, double t) {
    double d1 = (std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t));
    double d2 = d1 - sigma * std::sqrt(t);
    return s * norm_cdf(d1) - k * std::exp(-r * t) * norm_cdf(d2);
}

double bs_put_ok(double s, double k, double r, double sigma, double t) {
    double d1 = (std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t));
    double d2 = d1 - sigma * std::sqrt(t);
    return k * std::exp(-r * t) * norm_cdf(-d2) - s * norm_cdf(-d1);
}

double bs_call_nodisc(double s, double k, double r, double sigma, double t) {
    double d1 = (std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t));
    return s * norm_cdf(d1) - k * norm_cdf(d1 - sigma * std::sqrt(t));
}
double bs_put_nodisc(double s, double k, double r, double sigma, double t) {
    double d1 = (std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t));
    return k * norm_cdf(-(d1 - sigma * std::sqrt(t))) - s * norm_cdf(-d1);
}
double bs_put_buggy(double s, double k, double r, double sigma, double t) {
    double d1 = (std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t));
    double d2 = d1 - sigma * std::sqrt(t);
    return k * std::exp(-r * t) * norm_cdf(d2) - s * norm_cdf(-d1);
}
double bs_delta_ok(double s, double k, double r, double sigma, double t) {
    return norm_cdf((std::log(s / k) + (r + 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t)));
}
double bs_delta_d2(double s, double k, double r, double sigma, double t) {
    return norm_cdf((std::log(s / k) + (r - 0.5 * sigma * sigma) * t) / (sigma * std::sqrt(t)));
}
double bs_delta_disc(double s, double k, double r, double sigma, double t) {
    return std::exp(-r * t) * bs_delta_ok(s, k, r, sigma, t);
}
double tree_call_ok(double s, double k, double r, double sigma, double t, int n) {
    return binomial_price(Call(k), s, r, sigma, t, n, false);
}
double tree_call_capped(double s, double k, double r, double sigma, double t, int n) {
    return binomial_price(Call(k), s, r, sigma, t, n > 64 ? 64 : n, false);
}
double tree_call_nodisc(double s, double k, double r, double sigma, double t, int n) {
    return binomial_price(Call(k), s, 0.0, sigma, t, n, false);
}
double bs_call_lowvol(double s, double k, double r, double sigma, double t) {
    if (sigma < 1e-3) return 0.0;  // a 'guard' that is wrong
    return bs_call_ok(s, k, r, sigma, t);
}
typedef double (*Pricer)(double, double, double, double, double);
Pricer bs_call = bs_call_ok, bs_put = bs_put_ok, bs_delta_call = bs_delta_ok;
double (*tree_call)(double, double, double, double, double, int) = tree_call_ok;

