#include <algorithm>
#include <cmath>
#include <vector>

// Node (i, j) of the triangle lives at i * (i + 1) / 2 + j.
int tri(int i, int j) { return i * (i + 1) / 2 + j; }

double flat_american_put(double s, double k, double r, double sigma, double t, int n) {
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1 / growth;
    int nodes = (n + 1) * (n + 2) / 2;
    std::vector<double> price;
    price.reserve(nodes);                      // one allocation, no copies
    for (int i = 0; i <= n; ++i) {
        double p = s * std::pow(d, i);         // node (i, 0)
        for (int j = 0; j <= i; ++j) {
            price.push_back(p);
            p *= u * u;
        }
    }
    std::vector<double> v(nodes);
    for (int j = 0; j <= n; ++j) v[tri(n, j)] = std::max(k - price[tri(n, j)], 0.0);
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j) {
            double hold = disc * (q * v[tri(i + 1, j + 1)] + (1 - q) * v[tri(i + 1, j)]);
            v[tri(i, j)] = std::max(hold, k - price[tri(i, j)]);
        }
    return v[0];
}

